document.addEventListener("DOMContentLoaded",function(){function n(n){return n>=1e6?`$${(n/1e6).toFixed(1)}M`:n>=1e3?`$${(n/1e3).toFixed(0)}K`:n.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function s(n){return`${n.toFixed(1)}%`}function e(n,s,e,t="info"){return`\n      <div class="insight-card ${t}">\n        <h6>${n}</h6>\n        <div class="metric-value">${s}</div>\n        <div class="metric-subtitle">${e}</div>\n      </div>\n    `}const t=document.getElementById("gallery-form"),i=document.getElementById("gallery-result");t&&t.addEventListener("submit",function(t){t.preventDefault();const a=parseFloat(document.getElementById("gallery-area").value),o=parseFloat(document.getElementById("renovation-cost-sqm").value),r=parseFloat(document.getElementById("equipment-cost").value),l=parseFloat(document.getElementById("initial-expenses").value),d=parseFloat(document.getElementById("avg-artwork-price").value),c=parseFloat(document.getElementById("monthly-sales").value),v=parseFloat(document.getElementById("commission-rate").value),p=parseFloat(document.getElementById("additional-services").value),u=parseFloat(document.getElementById("rent").value),m=parseFloat(document.getElementById("staff-costs").value),g=parseFloat(document.getElementById("marketing").value),$=parseFloat(document.getElementById("utilities-other").value);if(a<=0||c<=0||d<=0)return i.innerHTML='<div class="error">Please enter valid values for all fields.</div>',void 0;const h=a*o,w=h+r+l,f=c*d,y=f*(v/100),b=y+p,k=u+m+g+$,E=b-k,F=12*E,I=E/b*100,B=w/F,x=F/w*100,M=b/a,P=y/c,A=k/a;let D="info";E<0?D="warning":I>35&&(D="success");let S="info";x<15?S="warning":x>30&&(S="success");let R="info";B>5?R="warning":B<=3&&(R="success"),i.innerHTML=`\n        <div class="business-plan-results">\n          <h3>🎨 Art Gallery Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n            ${e("💰 Total Investment",n(w),`${a} sq ft`,"info")}\n            ${e("📈 Monthly Profit",n(E),`Margin: ${s(I)}`,D)}\n            ${e("⏱️ Payback Period",`${B.toFixed(1)} years`,`ROI: ${s(x)}`,R)}\n            ${e("🎯 Sales Volume",`${c} artworks/month`,`${n(P)} commission`,"info")}\n          </div>\n\n          <div class="financial-breakdown">\n            <h4>💼 Detailed Financial Analysis</h4>\n            \n            <div class="section">\n              <h5>🏗️ Startup Costs</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Renovation & build-out (${a} sq ft × ${n(o)})</span>\n                  <span>${n(h)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Equipment (lighting, security, furniture)</span>\n                  <span>${n(r)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Initial expenses (marketing, initial artworks)</span>\n                  <span>${n(l)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Startup Investment</strong></span>\n                  <span><strong>${n(w)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💵 Monthly Revenue</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Artwork sales (${c} × ${n(d)})</span>\n                  <span>${n(f)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Gallery commission (${s(v)})</span>\n                  <span>${n(y)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Additional services (workshops, events)</span>\n                  <span>${n(p)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Revenue</strong></span>\n                  <span><strong>${n(b)}</strong></span>\n                </div>\n              </div>\n            </div>\n\n            <div class="section">\n              <h5>💸 Monthly Expenses</h5>\n              <div class="breakdown-table">\n                <div class="breakdown-row">\n                  <span>Rent/lease payments</span>\n                  <span>${n(u)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Staff (curator, assistant, security)</span>\n                  <span>${n(m)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Marketing & promotion</span>\n                  <span>${n(g)}</span>\n                </div>\n                <div class="breakdown-row">\n                  <span>Utilities & other expenses</span>\n                  <span>${n($)}</span>\n                </div>\n                <div class="breakdown-row total">\n                  <span><strong>Total Monthly Expenses</strong></span>\n                  <span><strong>${n(k)}</strong></span>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card info">\n              <h6>🔄 Space Efficiency</h6>\n              <div class="metric-subtitle">\n                Revenue per sq ft: <strong>${n(M)}/month</strong><br>\n                Costs per sq ft: <strong>${n(A)}/month</strong><br>\n                Average commission: <strong>${n(P)}</strong>\n              </div>\n            </div>\n            <div class="insight-card ${v>=50?"success":"info"}">\n              <h6>📊 Revenue Structure</h6>\n              <div class="metric-subtitle">\n                Sales commission: <strong>${s(y/b*100)}</strong><br>\n                Additional services: <strong>${s(p/b*100)}</strong><br>\n                Commission rate: <strong>${s(v)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="insight-cards">\n            <div class="insight-card ${E>0?"success":"warning"}">\n              <h6>📈 Profitability Forecast</h6>\n              <div class="metric-subtitle">\n                Annual profit: <strong>${n(F)}</strong><br>\n                Weekly profit: <strong>${n(F/52)}</strong><br>\n                Daily profit: <strong>${n(F/365)}</strong>\n              </div>\n            </div>\n            <div class="insight-card info">\n              <h6>💡 Growth Potential</h6>\n              <div class="metric-subtitle">\n                With +50% sales: <strong>${n(E+.5*y)}/month</strong><br>\n                With 20% price increase: <strong>${n(E+.2*y)}/month</strong><br>\n                Turnover per sq ft: <strong>${n(f/a)}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class="recommendations">\n            <h4>🎯 Optimization Recommendations</h4>\n            <ul>\n              ${I<20?"<li>⚠️ Low profitability. Consider increasing commission rates or reducing costs.</li>":""}\n              ${c<5?"<li>📍 Low sales volume. Improve curatorial program and marketing efforts.</li>":""}\n              ${B>5?"<li>⏰ Long payback period. Optimize startup costs or increase revenue streams.</li>":""}\n              ${c>15?"<li>✅ High sales volume! Consider gallery expansion or premium pricing.</li>":""}\n              ${I>35?"<li>🎉 Excellent profitability! Invest in growth and expansion opportunities.</li>":""}\n              <li>🎨 Develop relationships with local artists and art schools for emerging talent.</li>\n              <li>📱 Build strong online presence with virtual exhibitions and e-commerce.</li>\n              <li>🎪 Host regular art events, openings, and collector receptions.</li>\n              <li>🤝 Partner with interior designers for commercial art placement.</li>\n              <li>💼 Develop corporate client base for office art installations.</li>\n              <li>📚 Add educational programs and workshops for stable revenue.</li>\n              <li>🌐 Participate in art fairs and international exhibitions.</li>\n              <li>🎯 Focus on unique artists and exclusive representation agreements.</li>\n              <li>📊 Use data analytics to track best-selling artists and styles.</li>\n            </ul>\n          </div>\n\n          <div class="print-section">\n            <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n            <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n          </div>\n        </div>\n      `,window.galleryBusinessData={"Gallery Area (sq ft)":a,"Total Investment ($)":w,"Monthly Revenue ($)":b,"Monthly Expenses ($)":k,"Monthly Profit ($)":E,"Annual Profit ($)":F,"Profit Margin (%)":I,"Annual ROI (%)":x,"Payback Period (years)":B,"Monthly Sales (units)":c,"Average Artwork Price ($)":d,"Gallery Commission (%)":v,"Revenue per sq ft ($)":M}}),window.downloadCSV=function(){if(!window.galleryBusinessData)return;const n=Object.entries(window.galleryBusinessData).map(([n,s])=>`"${n}","${"number"==typeof s?s.toFixed(2):s}"`).join("\n"),s=new Blob(["\ufeffMetric,Value\n"+n],{type:"text/csv;charset=utf-8;"}),e=document.createElement("a");e.href=URL.createObjectURL(s),e.download="art-gallery-business-plan.csv",e.click()}});